import{c as e,Q as d,j as o,m as a}from"./chunks/framework.CWBTDBPu.js";const _=JSON.parse('{"title":"YuRandomTeleport PlaceholderAPI","description":"","frontmatter":{"title":"YuRandomTeleport PlaceholderAPI"},"headers":[],"relativePath":"plugins/items/yu-random-teleport/placeholders.md","filePath":"plugins/items/yu-random-teleport/placeholders.md"}'),r={name:"plugins/items/yu-random-teleport/placeholders.md"};function c(l,t,p,s,n,u){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="yurandomteleport-placeholderapi" tabindex="-1">YuRandomTeleport PlaceholderAPI <a class="header-anchor" href="#yurandomteleport-placeholderapi" aria-label="Permalink to &quot;YuRandomTeleport PlaceholderAPI&quot;">​</a></h1><p>安装 PlaceholderAPI 且 <code>integrations.placeholderapi.enabled: true</code> 时，插件注册标识符 <code>yurtp</code>。这些变量只读取无锁快照，不会加载区块或查询 Vault。</p><h2 id="全局变量" tabindex="-1">全局变量 <a class="header-anchor" href="#全局变量" aria-label="Permalink to &quot;全局变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yurtp_version%</code></td><td>插件版本。</td></tr><tr><td><code>%yurtp_platform%</code></td><td><code>bukkit</code> 或 <code>folia</code>。</td></tr><tr><td><code>%yurtp_default_language%</code></td><td>实际生效的默认语言。</td></tr><tr><td><code>%yurtp_total_success%</code></td><td>本次启动以来成功次数。</td></tr><tr><td><code>%yurtp_total_failed%</code></td><td>本次启动以来失败次数。</td></tr><tr><td><code>%yurtp_total_cancelled%</code></td><td>本次启动以来取消次数。</td></tr></tbody></table><h2 id="玩家变量" tabindex="-1">玩家变量 <a class="header-anchor" href="#玩家变量" aria-label="Permalink to &quot;玩家变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yurtp_cooldown%</code></td><td>剩余冷却秒数，向上取整。</td></tr><tr><td><code>%yurtp_cooldown_seconds%</code></td><td><code>%yurtp_cooldown%</code> 的别名。</td></tr><tr><td><code>%yurtp_cooldown_ms%</code></td><td>剩余冷却毫秒数。</td></tr><tr><td><code>%yurtp_cooldown_formatted%</code></td><td><code>2m 5s</code> 或 <code>8s</code> 格式。</td></tr><tr><td><code>%yurtp_ready%</code></td><td>无冷却且无待处理请求时为 <code>true</code>。</td></tr><tr><td><code>%yurtp_pending%</code></td><td>正在等待或搜索时为 <code>true</code>。</td></tr><tr><td><code>%yurtp_status%</code></td><td>小写的 <code>TeleportStatus</code>，无快照时为 <code>idle</code>。</td></tr><tr><td><code>%yurtp_last_world%</code></td><td>最近快照的世界名。</td></tr><tr><td><code>%yurtp_last_x%</code> / <code>%yurtp_last_y%</code> / <code>%yurtp_last_z%</code></td><td>最近快照坐标。</td></tr><tr><td><code>%yurtp_last_updated%</code></td><td>快照更新时间，Unix 毫秒。</td></tr><tr><td><code>%yurtp_has_last_location%</code></td><td>快照包含目标世界时为 <code>true</code>。</td></tr></tbody></table><p>没有玩家上下文时，玩家变量返回空字符串；没有快照时位置变量也返回空字符串，<code>last_updated</code> 返回 <code>0</code>。未知变量按 PlaceholderAPI 约定返回 <code>null</code>。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/papi parse me %yurtp_status%</span></span>
<span class="line"><span>/papi parse me %yurtp_cooldown_formatted%</span></span>
<span class="line"><span>/papi parse me %yurtp_platform%</span></span></code></pre></div><p>修改集成开关后执行 <code>/yurtp reload</code>，插件会注销并按新配置重新注册扩展。</p>`,10)])])}const h=e(r,[["render",c]]);export{_ as __pageData,h as default};
